std::string read(const std::filesystem::path& p){std::ifstream f(p);return {std::istreambuf_iterator<char>(f),{}};}
CombatEntry fixture(const CombatContent& c,const SessionEntry& state,int map,TilePosition tile){auto e=c.entries.at("post-pickup");e.map=map;e.playerTile=tile;e.direction=Direction::Up;e.positions.clear();e.directions.clear();e.pages.clear();e.through.clear();e.session=state;return e;}
void idle(CombatScene& scene){for(int n=0;n<12000;++n){scene.update(n%8==0?key():InputFrame{});scene.takePresentation();if(scene.foreground()==ForegroundKind::None&&!scene.dialogue().active()&&!scene.world().player().motion.moving()){return;}}throw std::runtime_error("Cargo source tail stalled");}
void rules(const CombatContent& c,const SaveSnapshot& source,const std::filesystem::path& root){
 auto restored=prepareRestore(c,source);const auto base=restored.session->exportState();int cases=0;
 for(int form=0;form<3;++form){auto e=fixture(c,base,183,{25,8});e.session.skills.erase(3);e.session.skills.erase(4);if(form==0){e.session.skills.insert(3);}if(form==1){e.session.skills.insert(4);}GameSession s(c.items,e.session,c.facts);CombatScene scene(c,s,e,safe);const auto inv=s.exportState().inventory;const auto generation=scene.generation();scene.update(key());idle(scene);need(scene.mapId()==204&&scene.world().player().motion.tile()==TilePosition{14,25}&&scene.generation()!=generation,"Door source transfer failed");need(!s.knowsSkill(3)&&s.knowsSkill(4)==(form<2)&&s.exportState().inventory==inv&&s.flag(1)&&s.flag(18)&&!s.flag(13),"Skill tail/control/inventory contract");++cases;}
 {auto e=fixture(c,base,183,{25,8});e.session.worldFlags[c.facts.switches.at(530)]=false;e.session.inventory[111]=1;GameSession s(c.items,e.session,c.facts);CombatScene scene(c,s,e,safe);scene.update(key());idle(scene);need(scene.mapId()!=204&&!s.flag(577),"Residual I111 bypassed530 warehouse gate");++cases;}
 {auto e=fixture(c,base,183,{25,8});e.session.skills.erase(4);e.session.skills.insert(3);GameSession s(c.items,e.session,c.facts);bool reject=true;CombatScene scene(c,s,e,safe,[&](const SceneDefinition& d){if(reject&&d.backgroundPath.filename()=="map-204-background.png"){throw std::runtime_error("isolated cargo candidate rejection");}});const auto generation=scene.generation();scene.update(key());for(int n=0;n<2000&&scene.transferError().empty();++n){scene.update({});scene.takePresentation();}need(scene.mapId()==183&&scene.generation()==generation&&!scene.transferError().empty()&&s.knowsSkill(3)&&!s.knowsSkill(4)&&!s.flag(577),"Failed source transfer published skill/scene");reject=false;idle(scene);need(scene.mapId()==204&&scene.generation()!=generation&&s.knowsSkill(4)&&!s.knowsSkill(3),"Retry failed source tail");scene.deactivate();const auto state=s.exportState();for(int n=0;n<100;++n){scene.update(key());}need(s.exportState()==state,"Retired source wrote state");++cases;}
 {auto e=fixture(c,base,204,{14,6});e.session.worldFlags[c.facts.switches.at(577)]=true;e.session.worldFlags[c.facts.switches.at(578)]=true;GameSession s(c.items,e.session,c.facts);bool reject=true;CombatScene scene(c,s,e,safe,[&](const SceneDefinition& d){if(reject&&d.backgroundPath.filename()=="map-206-background.png"){throw std::runtime_error("isolated elevator candidate failure");}});const auto inv=s.exportState().inventory;const auto generation=scene.generation();InputFrame move;move.movement=Direction::Up;scene.update(move);for(int n=0;n<12000&&scene.transferError().empty();++n){scene.update({});scene.takePresentation();}need(scene.mapId()==204&&scene.generation()==generation&&!scene.transferError().empty()&&s.flag(578)&&s.flag(529)&&s.exportState().inventory==inv,"Elevator failure lost old victory/world/alarm");reject=false;idle(scene);need(scene.mapId()==206&&scene.generation()!=generation&&s.flag(529)&&s.exportState().inventory==inv,"Elevator retry duplicated file/closed alarm");++cases;}
 {auto e=fixture(c,base,204,{14,25});GameSession s(c.items,e.session,c.facts);CombatScene scene(c,s,e,safe);for(int x:{14,13,11,12,10,16,15,17,18}){need(!next(scene.world(),{x,5}),"Unwon platform exit reachable");}++cases;}
 {const auto prepared=Json::parse(read(c.directory/"g6-cargo-prepared-source.json"));const auto& cells=prepared.at("projection").at("platform_contract").at("changed_tiles");auto definition=c.maps.at(204);definition.objects.clear();ExplorationScene before(definition),after(definition);auto oldMasks=definition.passageMasks,newMasks=oldMasks;for(const auto& row:definition.upperTileReplacements){after.substituteUpperTile(row.fromIndex,row.toIndex);}for(const auto& cell:cells){const auto xy=cell.at("xy").get<std::array<int,2>>();const int index=xy[1]*definition.width+xy[0];need(oldMasks.at(index)==cell.at("old_passage"),"Changed original platform mask");newMasks.at(index)=cell.at("new_passage");}need(cells.size()==36&&after.substitutedUpperTiles().size()==24,"Platform original36/24 definition");for(const auto& cell:cells){const auto xy=cell.at("xy").get<std::array<int,2>>();auto probe=before.player();probe.motion=CharacterMotion({xy[0],xy[1]},Direction::Up,probe.motion.speed());for(auto direction:{Direction::Up,Direction::Right,Direction::Down,Direction::Left}){auto target=adjacentTile(probe.motion.tile(),direction);const int out=direction==Direction::Up?8:direction==Direction::Right?4:direction==Direction::Down?1:2,in=direction==Direction::Up?1:direction==Direction::Right?2:direction==Direction::Down?8:4;const auto expected=[&](const std::vector<int>& masks){return target.x>=0&&target.x<definition.width&&target.y>=0&&target.y<definition.height&&(masks[xy[1]*definition.width+xy[0]]&out)&&(masks[target.y*definition.width+target.x]&in);};need(before.canMove(probe,direction)==expected(oldMasks)&&after.canMove(probe,direction)==expected(newMasks),"36 platform source before/after terrain edge mismatch");}}++cases;}
 std::ofstream(root/"rules-result.json")<<Json{{"kind","controlled source contract variations; not natural acceptance"},{"cases",cases},{"skill3_to4_after_transfer",true},{"already4_and_no3",true},{"residual111_gate_rejected",true},{"candidate_failure_preserves_generation_skills",true},{"retired_writes",false},{"unwon_nine_exits_blocked",true},{"original36_cells_144_edges_before_after",true}}.dump(2)<<'\n';std::cout<<"G6-06 full33/skill variations/530 gate/candidate retry/generation PASS\n";
}
using g6cargo::enter;
using g6cargo::prompt;
