void natural(const CombatContent& c,const std::string& raw,const std::filesystem::path& root){
 std::filesystem::create_directories(root/"slots");std::ofstream(root/"slots/slot-01.json")<<raw;auto rng=std::make_shared<std::mt19937>(2042026);G2NaturalDriver d(c,root,"public-inputs.jsonl",[rng](int lo,int hi){return std::uniform_int_distribution<int>(lo,hi)(*rng);});d.game.configureSaveDirectory(root/"slots");DoraRender render(d.game,c,root/"frames");std::set<std::uint64_t> broadcasts;bool doorBefore=false,landed=false;int sounds=0;
 d.observe=[&](const PresentationEvent& ev){render.pending.push_back(ev);sounds+=ev.kind==PresentationEvent::Kind::Sound;};d.afterTick=[&]{render.tick();if(d.game.mapId()==183&&d.game.foreground()==ForegroundKind::Content){doorBefore=true;if(d.game.dialogue().active()){broadcasts.insert(d.game.dialogue().view().request);}if(d.game.world().lowerTileMapping()[63]==60){render.frame("natural-six-door-tiles");}}if(d.game.mapId()==204&&!landed){landed=true;render.frame("natural204-entry");}};
 d.load();need(d.game.mapId()==183&&!d.game.session().flag(577)&&!d.game.session().flag(578),"Natural03 source Load facts");const int initialCount=d.game.session().saveCount(),stat=d.game.session().variable(399);const int files=d.game.session().count(180);enter(d);for(int x:{14,13,11,12,10,16,15,17,18}){need(!next(d.game.world(),{x,5}),"Unwon elevator reachable");}need(doorBefore&&broadcasts.size()==2&&d.game.session().knowsSkill(4)&&!d.game.session().knowsSkill(3),"Natural complete broadcast/skill tail absent");prompt(d,1);need(!d.game.session().flag(577)&&d.game.session().count(180)==files,"No choice changed files/start");d.walk({3,6});for(int n=0;n<20;++n){d.press();}d.settle();d.item(1);d.equip(22);prompt(d,0);fight(d);
 need(d.game.world().substitutedUpperTiles().size()==24&&d.game.session().count(180)==files&&d.game.session().count(195)==0,"Natural victory/file single return/platform");render.frame("natural-victory-platform");directSave(d);const auto saved=SaveFiles(c,root/"slots").read(2);need(read(root/"slots/slot-01.json")==raw,"Isolated source slot changed");need(saved.session.saveCount==initialCount+1&&d.game.session().variable(399)==stat&&saved.session.worldFlags.at(c.facts.switches.at(578)),"Natural direct save counter/platform");elevator(d,14);render.frame("natural206-cargo");cargo(d,8);render.frame("natural209-final-battle");
 std::ofstream(root/"natural-result.json")<<Json{{"kind","genuine03 isolated disk -> only public application input"},{"runtime_progress_injection",false},{"steps",d.ticks},{"maps",d.maps},{"door_broadcast_messages",broadcasts.size()},{"door_commands",33},{"no_then_yes",true},{"warehouse_victory",true},{"direct_victory_save_count",saved.session.saveCount},{"E29_public_repeat_grants",20},{"actual_spray_consumed",21-saved.session.inventory.at(1)},{"V399_unchanged",true},{"reused_actual_files_once",true},{"cargo_door",3},{"actual_final_battle_map",209},{"sound_submissions",sounds},{"frames",render.frames}}.dump(2)<<'\n';
}
void exits(const CombatContent& c,const std::string& raw,const std::filesystem::path& root){
 const auto saved=decodeSave(c,raw);auto restored=prepareRestore(c,saved);const auto state=restored.session->exportState();need(restored.scene->mapId()==204&&state.worldFlags.at(c.facts.switches.at(578)),"Exit sample must be actual victory save");
 int exits=0;for(int x:{14,13,11,12,10,16,15,17,18}){auto content=c;content.entries["exit-variation"]=fixture(c,state,204,{14,25});G2NaturalDriver d(content,root,"exit-"+std::to_string(x)+".jsonl");std::unique_ptr<DoraRender> render;if(x==14){render=std::make_unique<DoraRender>(d.game,content,root/"frames");d.observe=[&](const PresentationEvent& event){render->pending.push_back(event);};d.afterTick=[&]{render->tick();};}d.game.restartDevelopmentEntry("exit-variation");d.settle();if(render){d.walk({14,6});d.settle();render->frame("actual-victory-state-platform36");}need(d.game.world().substitutedUpperTiles().size()==24,"Actual saved578 rebuild lost platform");const auto inv=d.game.session().exportState().inventory;elevator(d,x);need(d.game.session().exportState().inventory==inv,"Rebuilt578 replayed CE167");++exits;}
 for(int y:{7,8,9}){auto content=c;content.entries["cargo-variation"]=fixture(c,state,204,{14,25});G2NaturalDriver d(content,root,"cargo-"+std::to_string(y)+".jsonl");d.game.restartDevelopmentEntry("cargo-variation");d.settle();elevator(d,14);cargo(d,y);}
 std::ofstream(root/"exits-result.json")<<Json{{"kind","actual victory state, explicitly relocated independent path variations"},{"nine_exits",exits},{"different_first_exit_paths",true},{"three_cargo_doors_reach_actual209",true},{"rebuild_does_not_repeat_CE167",true}}.dump(2)<<'\n';std::cout<<"G6-06 nine independent exits/three doors/578 rebuild/file preservation PASS\n";
}
void load(const CombatContent& c,const std::string& raw,const std::filesystem::path& root){std::filesystem::create_directories(root/"slots");std::ofstream(root/"slots/slot-01.json")<<raw;G2NaturalDriver d(c,root);d.game.configureSaveDirectory(root/"slots");const auto saved=decodeSave(c,raw);DoraRender render(d.game,c,root/"frames");d.observe=[&](const PresentationEvent& event){render.pending.push_back(event);};d.afterTick=[&]{render.tick();};d.load();const auto inv=d.game.session().exportState().inventory;need(d.game.mapId()==204&&d.game.world().substitutedUpperTiles().size()==24&&d.game.session().flag(578)&&d.game.session().saveCount()==saved.session.saveCount,"Actual independent direct Load platform");d.load();need(d.game.session().exportState().inventory==inv&&d.game.session().saveCount()==saved.session.saveCount,"Repeated direct Load replayed file/count");elevator(d,18);cargo(d,9);render.frame("actual-loaded-final-battle-ready");std::ofstream(root/"load-result.json")<<Json{{"separate_process_titleLoad",true},{"repeatedLoad",true},{"actual_direct_victory_state",true},{"platform_rebuilt",true},{"reaches_actual209",true},{"actual_final_intro581_visible_controls",true}}.dump(2)<<'\n';std::cout<<"G6-06 actual direct victory independent title/repeatedLoad/platform/final209 PASS\n";}
