int main(int argc,char** argv){try{std::cout.setf(std::ios::unitbuf);need(argc==5,"cargo package actual03-or-victory-save output rules|natural|exits|load");auto c=loadCombatContent(argv[1]);auto raw=read(argv[2]);auto saved=decodeSave(c,raw);std::filesystem::create_directories(argv[3]);std::string mode=argv[4];if(mode=="natural"){natural(c,raw,argv[3]);}else if(mode=="exits"){exits(c,raw,argv[3]);}else if(mode=="load"){load(c,raw,argv[3]);}else{rules(c,saved,argv[3]);}return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
